(* Hysteresis fill control *)
IF NOT High_Level AND NOT Fault_State AND Emergency_Stop THEN
    Fill_Pump := TRUE;
END_IF;
IF High_Level OR Fault_State OR NOT Emergency_Stop THEN
    Fill_Pump := FALSE;
END_IF;

(* Drain when above drain setpoint *)
IF High_Level AND Drain_Enable AND NOT Fault_State THEN
    Drain_Valve := TRUE;
END_IF;
IF Low_Level OR Fault_State THEN
    Drain_Valve := FALSE;
END_IF;

(* Alarms *)
High_High_Alarm := High_Level AND Fill_Pump;
Low_Low_Alarm   := NOT Low_Level AND NOT Fill_Pump;
